import {record} from 'rrweb';
import { deflate } from 'pako/dist/pako_deflate';
import * as requestUtil from '../request-util';
import { MMVideoOption } from '../types';
import Recorder from '../recorder';

export default class VideoRecorder extends Recorder {
    private stopFn: Function | undefined;
    private stopHandlers: Function[];
    private worker: Worker | undefined;
    private events = [];
    private bizServiceUrl: string;
    private proxyServerUrl: string;
    private resourceServerUrl: string;
    private workerScriptUrl: string | null;
    private delay: number;
    private threshold: number;
    private timer: NodeJS.Timeout;
    private nonce: number;
    private sequenceNo: number;
    private depositNo: string;

    private sending: boolean;

    constructor(option: MMVideoOption) {
        super(option);
        this.bizServiceUrl = option.collectorServer;
        this.proxyServerUrl = option.proxyServer;
        this.resourceServerUrl = option.resourceServer;
        this.workerScriptUrl = option.workerScriptUrl;
        this.delay = option.delay || 2000;
        this.threshold = option.threshold || 3;
        this.depositNo = option.busDespositNo || '';

        this.sequenceNo = 0;
        this.nonce = Math.round(Math.random() * 1000000);
        this.stopFn = undefined;
        this.sending = false;

        this.stopHandlers = [];
        
        

        // 图片资源抓取时使用
        window.mmResourceDomain = this.resourceServerUrl;
        window.mmProxyServer = this.proxyServerUrl;
        window.mmSystemCode = this.systemCode;
        window.mmPageVersion = this.pageVersion;

        // 异常情况监听处理
        const _this = this;
        window.onbeforeunload = function(){
           _this.stop(this.doNothing, this.doNothing);
        };
    }

    public close(): void {
      this.stopWorker();
    }

    public start(ok: Function, fail: Function): void {
      const that = this;
      // 检查是否调用了stop
      if (this.stopFn) {
        console.warn('A new recording was started before the previous one was stopped');
        this.stop(() => {
          that.doStart(ok, fail);
        }, fail);
      } else {
        that.doStart(ok, fail);
      }
    }

    public doStart(ok: Function, fail: Function): void {
      const that = this;
      try {
        if (!this.depositNo) {
            this.depositNo = requestUtil.getDepositNo() || '';
            if (!this.depositNo) {
              this.checkErrorCallBack('获取存证单号数据异常', fail);
              return;
            }
        }
        requestUtil.setFileNo(this.depositNo);
        this.sequenceNo = 0;

        this.stopHandlers = [];

        // const stopWorker = this.startWorker(ok, fail);
        if (!this.worker) {
          this.startWorker(ok, fail);
        }

        this.startRecordWatcher(ok, fail);
        const stopRecord = this.startRecorder();

        this.stopFn = (okFun: Function, failFun: Function) => {
          stopRecord();
          this.stopRecordWatcher(okFun, failFun);
          // stopWorker();
        };
      }catch (e) {
        console.error('异常:', e);
        that.checkErrorCallBack('start接口异常', fail);
      }
    }

    public stop(ok: Function, fail: Function): void {
      if (this.stopFn) {
        this.stopHandlers.push(ok);
        this.stopFn(ok, fail);
        this.stopFn = undefined;
        this.worker?.postMessage({cmd: 'mm-stop'});
      } else {
        console.warn('stopFn is not defined');
        ok();
      }
      this.stopSend(ok,fail);
    }

     /**
     * 订单结束
     * @param status 状态
     * @param ok 成功回调
     * @param fail 失败回调
     */
     public stopSend(ok: Function, fail: Function): void {
      const _this = this;
      let depositNo = this.depositNo || requestUtil.getDepositNo();
      if (!depositNo) {
        this.checkErrorCallBack('存证单号数据异常', fail);
        return;
      }
      const statusRequestUrl = this.bizServiceUrl + '/deposite/stop';
      const request = requestUtil.getRequest('STOP');
      const fileSerial =requestUtil.getFileNo(depositNo);
      request.body = {
          depositNo, // requestUtil.getDepositNo()
          fileSerial:fileSerial,
          fileSeqNo:this.sequenceNo
      };
      requestUtil.ajax({
          url: statusRequestUrl,
          type: 'POST',
          data: request,
          dataType: 'json',
          contentType: 'application/json',
          async: true,
          success: (data) => {
              requestUtil.checkCallBack(data, ok, fail);
          },
          error: (e) => {
              console.error(e);
              requestUtil.checkErrorCallBack('停止接口异常', fail);
          },
      });
  }

    private startRecorder(): Function {
      const that = this;
      const stopRecord: Function = record({
          emit(event) {
              // 将 event 存入 events 数组中
              that.events.push(event);
              },
          recordCanvas: true,
      });
      return stopRecord;
    }

    private startWorker(ok: Function, fail: Function): Function {
      if (!this.workerScriptUrl) {
        console.warn('worker url is not provided, execute without worker');
        return this.doNothing;
      }

      const that = this;
      this.worker = new Worker(this.workerScriptUrl);
      this.worker.addEventListener('message', (ev) => {
        if (ev.data.ack === 'mm-closed') {
          if (that.worker) {
            that.worker.terminate();
          }
          that.worker = undefined;
        } else if (ev.data.ack === 'mm-stopped') {
          that.stopHandlers.forEach( (handler) => {
            handler();
          });
        } else {
          that.sendSnapshot(ev.data.url, ev.data.eventData, ok, fail);
        }
      });

      const stopFun = () => {
        if (this.worker) {
          this.stopWorker();
        }
      };

      return stopFun;
    }

    private stopWorker(): void {
      if (this.worker) {
        this.worker.postMessage({cmd: 'mm-terminate'});
      }
    }

    private startRecordWatcher (ok: Function, fail: Function) {
      let realDelay: number;
      let realThreshold: number;

      if (this.sequenceNo < 30) {
        realDelay = 200 * (1 + this.sequenceNo);
        realThreshold = 1 + this.sequenceNo;

        realDelay = (realDelay > this.delay) ? this.delay : realDelay;
        realThreshold = (realThreshold > this.threshold) ? this.threshold : realThreshold;
      } else {
        realDelay = this.delay;
        realThreshold = this.threshold;
      }

      this.timer = setTimeout(() => {
        if (this.events && this.events.length >= realThreshold && this.sending === false) {
          this.saveSnapshot(ok, fail);
        }
        this.startRecordWatcher(ok, fail);
      }, realDelay);
    }

    private stopRecordWatcher(ok: Function, fail: Function) {
      if (this.timer) {
        clearTimeout(this.timer);
      }
      this.saveSnapshot(ok, fail);
    }

    private saveSnapshot (ok: Function, fail: Function): void {
      if (this.events.length <= 0) {
        console.warn('无待发送数据');
        return this.checkCallBack({code: '200', message: '无待发送数据'}, ok, fail);
      }
      const depositNo = this.depositNo;
      if (!depositNo) {
        this.checkErrorCallBack('存证单号数据异常', fail);
        return;
      }
      const fileNoStr = requestUtil.getFileNo(depositNo);
      this.sequenceNo += 1;
      const sequenceNoStr = this.sequenceNo;  // requestUtil.getFileSeqNo();
      const requestUrl = this.bizServiceUrl + '/actual/save' + '/' + depositNo + '/' + fileNoStr + '/' + sequenceNoStr;
      const eventStr = JSON.stringify(this.events);
      this.events = [];
      if (this.worker) {
        console.warn('before postMessage', new Date().getTime());
        this.worker.postMessage({cmd: 'mm-compress', url: requestUrl, eventStr});
        console.warn('after postMessage', new Date().getTime());
      } else {
        console.warn('before deflate in main thread!', new Date().getTime());
        const eventData = deflate(encodeURIComponent(eventStr), { to: 'string', gzip: true});
        console.warn('after deflate in main thread!', new Date().getTime());
        this.sendSnapshot(requestUrl, eventData, ok, fail);
      }
    }

    private sendSnapshot(requestUrl: string, eventData: any, ok: Function, fail: Function, canRetry = true): void {
      const _this = this;
      this.sending = true;
      this.ajax({
        url: requestUrl,
        type: 'post',
        data: eventData,
        dataType: 'json',
        async: true,
        jsonFormat: false,
        contentType: 'application/octet-stream; charset=UTF-8', // 'application/json',
        authorization: requestUtil.getAuth(),
        success: (data) => {
          this.sending = false;
          if (data && data.code === '200') {
               _this.saveRemoteResource(ok, fail);
          } else {
            _this.checkCallBack(data, ok, fail);
          }
        },
        error: (e) => {
          if (canRetry) {
            return _this.sendSnapshot(requestUrl, eventData, ok, fail, false);
          }
          this.sending = false;
          console.error(e);
          _this.checkErrorCallBack('录屏接口异常', fail);
        },
      });
    }

    private saveRemoteResource(ok: Function, fail: Function|undefined): void {
      console.log('window.mmResources:'+window.mmResources);
      if (!window.mmResources || window.mmResources.length <= 0) {
        console.warn('saveRemoteResource11111');
        if (ok) {
          console.warn('saveRemoteResourceOk');
          ok();
        }
        return;
      }
      const _this = this;
      const requestUrl = this.bizServiceUrl + '/video/resource';
      const resourceSystemCode = window.mmSystemCode || 'def';
      const resourceVersion = window.mmPageVersion || '0.1';
      const mmResources = Array.from(window.mmResources);
      window.mmResources = [];
      const resources = {
        systemCode: resourceSystemCode,
        pageVersion: resourceVersion,
        images: mmResources,
        depositNo: this.depositNo,
      };

      this.ajax({
        url: requestUrl,
        type: 'POST',
        data: resources,
        dataType: 'json',
        contentType: 'application/json',
        async: true,
        success: (data) => {
          _this.checkCallBack(data, ok, fail);
        },
        error: (e) => {
          console.error(e);
          _this.checkErrorCallBack('资源接口异常', fail);
        }
      });
    }

    private checkCallBack(data: any, ok: Function, fail: Function|undefined) {
        if (data) {
            if (data.code === '200') {
                if (ok) {
                    ok(data);
                }
            } else {
                if (fail) {
                    const obj = requestUtil.getErrorResponse(data.code, data.message);
                    fail(obj);
                }
            }
        }
    }

    private checkErrorCallBack(message: string, fail: Function|undefined) {
        if (fail) {
            const obj = requestUtil.getErrorResponse('999', message);
            fail(obj);
        }
    }

    // 封装ajax
    private ajax (options: any) {
      options = options || {};  // 调用函数时如果options没有指定，就给它赋值{},一个空的Object
      options.type = (options.type || 'GET').toUpperCase(); // 请求格式GET、POST，默认为GET
      options.dataType = options.dataType || 'json';    // 响应数据格式，默认json
      options.async = options.async || true; // 设置同步或异步，默认异步
      options.timeout = options.timeout || 30000;  // 设置超时时间，默认20秒
      options.contentType = options.contentType || 'application/json'; // 设置提交方式，默认json格式  表单multipart/form-data
      options.jsonFormat = (options.jsonFormat !== false) ? true : false; // json序列化为string
      const xhr = new XMLHttpRequest();
      // 考虑兼容性
      /* if (window.XMLHttpRequest) {
          xhr = new XMLHttpRequest();
      }else if (window.ActiveObject){ // 兼容IE6以下版本
          xhr = new ActiveXobject('Microsoft.XMLHTTP');
      } */

      // 启动并发送一个请求
      if (options.type === 'GET') {
          const params = this.formatParams(options.data); // options.data请求的数据
          xhr.open('GET', options.url + '?' + params, options.async);
          xhr.send(null);
      }else if (options.type === 'POST') {
          xhr.open('post', options.url, options.async);
          // 设置表单提交时的内容类型
          // Content-type数据请求的格式
          xhr.setRequestHeader('Content-Type', options.contentType);
          xhr.setRequestHeader('MM-Nonce', '' + this.nonce);
          xhr.setRequestHeader('Authorization', options.authorization);
          if (options.jsonFormat) {
            const postData = JSON.stringify(options.data);
            xhr.send(postData);
          } else {
            xhr.send(options.data);
          }
      }

      // 设置有效时间
      setTimeout(function(){
          if (xhr.readyState !== 4 ) {
              xhr.abort();
          }
      }, options.timeout);

      xhr.onreadystatechange = function(){
          if (xhr.readyState === 4) {
              const status = xhr.status;
              if (status >= 200 && status < 300 || status === 304) {
                  if (options.success) {
                      options.success(JSON.parse(xhr.responseText), xhr.responseXML);
                      // options.success(xhr.responseText, xhr.responseXML);
                  }
              } else {
                  if (options.error) {
                      options.error(status);
                  }
              }
          }
      };
    }

    // 格式化请求参数
    private formatParams(data: any): string {
        const arr = [];
        for (const name of Object.keys(data)) {
            arr.push(encodeURIComponent(name) + '=' + encodeURIComponent(data[name]));
        }
        arr.push(('v=' + Math.random()).replace('.', ''));
        return arr.join('&');
    }
}
