import { MMImageOption, MessageDetail, AppConfig, QueryProjectList, ImageUploadOptions } from '../types';
import html2canvas from 'html2canvas/dist/html2canvas.esm';
import * as requestUtil from '../request-util';
import Recorder from '../recorder';
import ImageRecorder from './image-recorder';

export default class ImageRecorderCanvas extends Recorder implements ImageRecorder {

    private bizServiceUrl: string;
    private appConfig: AppConfig;
    private depositNo: string;

    constructor(option: MMImageOption) {
        super(option);
        if (option.busDespositNo) {
            this.depositNo = option.busDespositNo;
        }
        this.bizServiceUrl = option.collectorServer;
        this.appConfig = { node: '', parameters: {}, maxWidth: 0 };
    }

    public getAppConfig(callback: Function): void {
        const fn = callback || this.doNothing;
        if (this.appConfig.node) {
            fn();
            return;
        }
        let requestData = requestUtil.getRequest('QUERYPROJECT');
        requestData.body.systemCode = this.systemCode;
        const requestUrl = this.bizServiceUrl + '/config/queryProject';
        const requestMethod = 'POST';
        const _this = this;
        requestUtil.ajax({
            url: requestUrl,
            type: requestMethod,
            data: requestData,
            dataType: 'json',
            contentType: 'application/json',
            async: true,
            success: (data: QueryProjectList) => {
                if (data.data.length > 0) {
                    if (data.data[0].nodeId) {
                        _this.appConfig.node = data.data[0].nodeId;
                    }
                    if (data.data[0].resolutionRatio) {
                        _this.appConfig.maxWidth = data.data[0].resolutionRatio;
                    }
                    if(data.message){
                        requestUtil.setAuth(data.message);
                    }
                }
                fn();
            },
        });
    }

    public imageUpload(object: MessageDetail, options: ImageUploadOptions): void {
        const _this = this;
        if (!options) {
            options = {
                delay: 0,
                dom_handler: this.doNothing,
                ok: this.doNothing,
                fail: this.doNothing,
            };
        }
        if (!options.delay) { options.delay = 0; }
        setTimeout(() => {
            if (!options.ok) { options.ok = _this.doNothing; };
            if (!options.fail) { options.fail = _this.doNothing; };
            if (!options.dom_handler) { options.dom_handler = _this.doNothing; };
            let existTarget = true;
            let targetDocument = document.getElementById(this.appConfig.node);
            if (!targetDocument) {
                targetDocument = document.body;
                existTarget = false;
            }
            const dom_handler = options.dom_handler;

            const height = targetDocument.scrollHeight;
            const width = targetDocument.scrollWidth;
            html2canvas(targetDocument, {
                useCORS: true,
                height,
                width,
                onclone: (dom: any) => {
                    if (existTarget) {
                        dom.getElementById(_this.appConfig.node).setAttribute('style', 'height:' + height + 'px');
                    }
                    if (typeof dom_handler === 'function') {
                        dom_handler(dom);
                    }
                    const noscript = dom.getElementsByTagName('noscript')[0];
                    if (noscript) {
                        noscript.parentNode.removeChild(noscript);
                    }
                },
                scale: 2,
            }).then(function (canvas: HTMLCanvasElement) {
                const imgBlob = canvas.toDataURL('image/gif', 0.3);
                _this.dealImage(imgBlob, width, height, function (base64: string) {
                    const requestUrl = _this.bizServiceUrl + '/deposite/messageDetail';
                    const depositNo = _this.depositNo || requestUtil.getDepositNo();
                    const messageDetailRequest = requestUtil.getRequest('MESSAGEUPLOAD');
                    messageDetailRequest.body = object;
                    messageDetailRequest.body.type = '1';
                    messageDetailRequest.body.base64Data = base64;
                    messageDetailRequest.body.depositNo = depositNo;
                    messageDetailRequest.body.fileSeqNo = parseInt(requestUtil.getImgFileSeqNo(), 10);
                    messageDetailRequest.body.nodeName = object.nodeName ? object.nodeName : document.title;
                    messageDetailRequest.body.browserVersion = requestUtil.getBrowserVersion();
                    messageDetailRequest.body.pageVersion = _this.pageVersion;
                    messageDetailRequest.body.recordeTime = requestUtil.getDateTime();

                    requestUtil.ajax({
                        url: requestUrl,
                        type: 'POST',
                        data: messageDetailRequest,
                        dataType: 'json',
                        contentType: 'application/json',
                        async: false,
                        success: (data: RequestInfo) => {
                            options.ok(data);
                        },
                        error: (e: RequestInfo) => {
                            console.error(e);
                            options.fail(e);
                        },
                    });
                });
            });
        }, options.delay);
    }

    public setDepositNo(depositNo: string) {
        this.depositNo = depositNo;
    }

    private dealImage(base64: string, width: number, height: number, callBack: Function) {
        const newImage = new Image();
        const quality = 1;  // 压缩系数0-1之间
        newImage.src = base64;
        newImage.setAttribute('crossOrigin', 'Anonymous');	// url为外域时需要
        newImage.onload = function () {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (ctx == null) {
                callBack();
                return;
            }
            canvas.width = width * 0.75;
            canvas.height = height * 0.75;
            // @ts-ignore
            ctx.drawImage(this, 0, 0, canvas.width, canvas.height);
            const b64 = canvas.toDataURL('image/jpeg', quality); // 压缩语句
            callBack(b64); // 必须通过回调函数返回，否则无法及时拿到该值
        };
    }
}
