import { rmCookie } from '../cookie-util';

const key = 'zkr_deposit_no_list'

export function addAndCleanFailureDepositNo(name: string) {
    for (let dep of getDepositNoList()) {
        rmCookie(dep)
        removeDepositNo(dep)
    }
    addDepositNo(name)
}

function addDepositNo(name: string) {
    setDepositNoList(getDepositNoList().concat(name));
}

function removeDepositNo(depositNo: string) {
    const removedDepositNo = getDepositNoList().filter((deposit_No: string) => {
        return deposit_No !== depositNo;
    });
    setDepositNoList(removedDepositNo);
    return removedDepositNo;
}

function setDepositNoList(depositNoList: Array<string>) {
    localStorage.setItem(key, JSON.stringify(depositNoList))
}



function getDepositNoList(): Array<string> {
    const listStr = localStorage.getItem(key);
    return listStr ? JSON.parse(listStr) : [];
}
