import * as requestUtil from './request-util';
import { MMOption, ImageUploadOptions } from './types';
import VideoRecorder from './video';
import { ImageRecorder, ImageRecorderImpl } from './image';
import TextRecorder from './text';
import { ResponseInfo, MessageDetail } from './types';
import { addAndCleanFailureDepositNo } from './deposit-no-manger';
import { generateKeyValueString } from './utils/lib';
import { aesKey, publicKey, aesEncrypt } from './utils/encryption'
import { sm3 } from 'sm-crypto'; // 引入 sm-crypto 的 SM3 模块
import JSEncrypt from 'jsencrypt'

export default class MagicMirror {
    private bizServiceUrl: string;
    private systemCode: string;
    private pageVersion: string;
    private depositNo: string;
    private videoRecorder: VideoRecorder;
    private imageRecorder: ImageRecorder;
    private textRecorder: TextRecorder;

    constructor(option: MMOption) {
        this.bizServiceUrl = option.collectorServer;
        if (option.busDespositNo) {
            this.depositNo = option.busDespositNo;
            requestUtil.setDepositNo(option.busDespositNo);
        }
        this.systemCode = option.systemCode;
        this.pageVersion = option.pageVersion;
        this.videoRecorder = new VideoRecorder(option);
        this.imageRecorder = new ImageRecorderImpl(option);
        this.textRecorder = new TextRecorder(option);
    }

    /**
     * 是否兼容当前浏览器
     */
    public isCompatible(): boolean {
        return true;
    }

    /**
     * 初始化订单回溯记录
     * @param ok 成功回调
     * @param fail 失败回调
     * @param businessId 业务ID
     */
    public init(ok: Function, fail: Function, businessId?: string): void {
        this.imageRecorder.getAppConfig(() => {
            if (!businessId) {
                const depositNo = this.depositNo || requestUtil.getDepositNo();
                if (!depositNo) {
                    requestUtil.checkErrorCallBack('未获取到存证编号', fail);
                    return;
                }
                this.depositNo = depositNo;
                // requestUtil.checkErrorCallBack('未获取到业务ID', fail);
                this.textRecorder.start();
                ok();
                return;
            }
            const _this = this;
            // 去掉存证单号和重置序号
            if (this.depositNo) {
                requestUtil.removeFileNo(this.depositNo);
            }
            this.depositNo = '';
            const requestUrl = this.bizServiceUrl + '/deposite/init';
            const requestMethod = 'POST';
            const requestData = requestUtil.getRequest('INIT');
            requestData.body = {
                systemCode: this.systemCode,
                pageVersion: this.pageVersion,
                browserVersion: requestUtil.getBrowserVersion(),
                businessId,
            };

            requestUtil.ajax({
                url: requestUrl,
                type: requestMethod,
                data: requestData,
                dataType: 'json',
                contentType: 'application/json',
                async: false,
                authorization: requestUtil.getAuth(),
                success: (data: ResponseInfo) => {
                    if (data) {
                        if (data.code === '200') {
                            if (data.data.depositNo) {
                                _this.depositNo = data.data.depositNo;
                                // _this.imageRecorder.setDepositNo(_this.depositNo);
                                requestUtil.setDepositNo(_this.depositNo);
                                // 记录历史存证编号，删除cookie中的文件序号
                                addAndCleanFailureDepositNo(_this.depositNo);
                            }
                        }
                    }
                    this.textRecorder.start();
                    requestUtil.checkCallBack(data, ok, fail);
                },
                error: (e: ResponseInfo) => {
                    console.error(e);
                    requestUtil.checkErrorCallBack('初始化接口异常', fail);
                },
            });
        });
        // if (!businessId) {
        //     requestUtil.checkErrorCallBack('未获取到业务ID', fail);
        //     return;
        // }

    }

    /**
     * 关联业务数据
     * @param data 业务数据对象
     * @param ok 成功回调
     * @param fail 失败回调
     */
    public attachData(data: MessageDetail, ok: Function, fail: Function): void {
        const requestUrl = this.bizServiceUrl + '/deposite/messageDetail';
        const depositNo = this.depositNo || requestUtil.getDepositNo();
        if (!depositNo) {
            if (fail) {
                requestUtil.checkErrorCallBack('获取存证单号异常', fail);
            }
            return;
        }
        const messageDetailRequest = requestUtil.getRequest('MESSAGEUPLOAD');

        // 加密 data 中的每个字段

        const encryptedData = this.encryptData(data);
        console.log('encryptedData:',encryptedData)
        
        messageDetailRequest.body = encryptedData; // 加密后的data对象
        messageDetailRequest.body.type = '2';
        messageDetailRequest.body.depositNo = depositNo;
        messageDetailRequest.body.fileSeqNo = requestUtil.getFileNo(depositNo);
        messageDetailRequest.body.nodeName = data.nodeName ? data.nodeName : document.title;
        messageDetailRequest.body.browserVersion = requestUtil.getBrowserVersion();
        messageDetailRequest.body.pageVersion = this.pageVersion;
        messageDetailRequest.body.recordeTime = requestUtil.getDateTime();

        const result  = generateKeyValueString(messageDetailRequest.body)
        console.log('result:',result)

        messageDetailRequest.sign = sm3(result) // 加密后的data对象

        const encrypt = new JSEncrypt()
        encrypt.setPublicKey(publicKey)
        console.log('aesKey-加密之前：',aesKey)
        const encrypted = encrypt.encrypt(aesKey.toString()) // 把aesKey进行非对称加密
        console.log('salt-加密之后：',encrypted)

        requestUtil.ajax({
            url: requestUrl,
            type: 'POST',
            data: messageDetailRequest,
            dataType: 'json',
            contentType: 'application/json',
            async: true,
            authorization: requestUtil.getAuth(),
            salt: encrypted, // 动态设置 token
            success: (r: ResponseInfo) => {
                requestUtil.checkCallBack(r, ok, fail);
            },
            // 异常处理
            error: (e: ResponseInfo) => {
                console.error(e);
                requestUtil.checkErrorCallBack('发送数据接口异常', fail);
            },
        });
    }

     /**
     * 加密 data 中的每个字段
     * @param data 业务数据对象
     */
     private encryptData(data: MessageDetail): MessageDetail {
        const encryptedData: MessageDetail = {} as MessageDetail;

        for (const key in data) {
            if (data.hasOwnProperty(key)) {
                const value = data[key];
                if (typeof value === 'string') {
                    // 对字符串字段进行 加密
                    encryptedData[key] = aesEncrypt(value, aesKey, aesKey);
                }
            }
        }

        return encryptedData;
    }

    /**
     * 开始录屏
     * @param ok 成功回调
     * @param fail 失败回调
     */
    public startVideo(ok: Function, fail: Function): void {
        this.videoRecorder.start(ok, fail);
    }

    /**
     * 结束录屏
     * @param ok 成功回调
     * @param fail 失败回调
     */
    public stopVideo(ok: Function, fail: Function): void {
        this.videoRecorder.stop(ok, fail);
    }

    /**
     * 开始监听操作事件并发送文本日志
     */
    public startText(): void {
        this.textRecorder.start();
    }

    /**
     * 截图
     * @param data 业务数据对象
     * @param ok 成功回调
     * @param fail 失败回调
     */
    public snapshot(data: any, options: ImageUploadOptions) {
        this.imageRecorder.imageUpload(data, options);
    }

    /**
     * 获取存证编号
     * @param data 存证编号
     */
    public getBusDespositNo(): string | undefined {
        if (this.depositNo) {
            return this.depositNo;
        }
        return requestUtil.getDepositNo();
    }

    /**
     * 订单结束
     * @param status 状态
     * @param ok 成功回调
     * @param fail 失败回调
     */
    public async end(status: string, ok: Function, fail: Function) {
        const _this = this;
        const statusRequestUrl = this.bizServiceUrl + '/deposite/end';
        const request = requestUtil.getRequest('DEEND');
        const depositNo = this.depositNo || requestUtil.getDepositNo();
        const fileSerial =requestUtil.getFileNo(this.depositNo);
        request.body = {
            depositNo,
            status,
            fileSerial:fileSerial
        };
        this.videoRecorder.close();
        await requestUtil.ajax({
            url: statusRequestUrl,
            type: 'POST',
            data: request,
            dataType: 'json',
            contentType: 'application/json',
            async: true,
            authorization: requestUtil.getAuth(),
            success: (data: ResponseInfo) => {
                if (data) {
                    if (data.code === '200') {
                        // 清除存证单号和重置序号
                        requestUtil.removeFileNo(_this.depositNo);
                        requestUtil.removeDepositNo();
                        _this.textRecorder.stop();
                        _this.depositNo = '';
                    }
                }
                requestUtil.checkCallBack(data, ok, fail);
            },
            error: (e: ResponseInfo) => {
                console.error(e);
                requestUtil.checkErrorCallBack('结束接口异常', fail);
            },
        });
    }
}
