export function getTextNo() {
    const text_no_key = 'zkr_text_no';

    var textNo = getCookie(text_no_key);
    if (!textNo) {
        textNo = '0'
        setCookie(text_no_key, textNo);
    } else {
        textNo = parseInt(textNo) + 1 + '';
        setCookie(text_no_key, textNo);

    }
    return (Array(4).join('0') + textNo).slice(-4)
}

export function getRequest(requestType: string) {
    let requestObj: RequestObj = {
        head: {
            uuid: getUuid(),
            cipherText: 'cipherText',
            requestType: requestType,
            requsetDate: new Date().getTime(),
        },
        body: {},
        sign:'',

    };
    return requestObj;
}

export function getErrorResponse(code: string, message: string) {
    let requestObj: ErrorResponse;
    requestObj = {
        code: code || '999',
        message: message || '',
    }
    return requestObj;
}

export function getDateTime() {
    const date = new Date();
    const time = date.getFullYear() + '-' + (date.getMonth() + 1) + '-' + date.getDate() + ' ' + date.getHours() + ':' + date.getMinutes() + ':' + date.getSeconds();
    return time;
}

function getUuid() {
    let s = [];
    const hexDigits = '0123456789abcdef';
    for (let i = 0; i < 36; i++) {
        s[i] = hexDigits.substr(Math.floor(Math.random() * 0x10), 1);
    }
    s[14] = '4'; // bits 12-15 of the time_hi_and_version field to 0010
    // @ts-ignore
    s[19] = hexDigits.substr((s[19] & 0x3) | 0x8, 1); // bits 6-7 of the clock_seq_hi_and_reserved to 01
    s[8] = s[13] = s[18] = s[23] = '-';

    return s.join('');
}

