import Recorder from '../recorder';
import { MMTextOption, ResponseInfo, Element, Track, ElementEvent } from '../types';
import * as requestUtil from '../request-util';

export default class TextRecorder extends Recorder {

    private listener: NodeJS.Timeout;
    private trackMap: any;
    private tempTrack: any;
    private bizServiceUrl: string;
    private depositNo: string;

    private textElementEvent: ElementEvent = {
        newTrack: (key: string) => {
            const track: Track = {
                key,
                startTime: new Date().getTime(),
                endTime: new Date().getTime(),
                value: '',
                label: '',
                type: '',
            };
            return track;
        },
        button2: (event: string, key: string, element: Element) => {
            if (event === 'click') {
                const track = this.textElementEvent.newTrack(key);
                track.label = element.innerText;
                track.type = '点击';
                this.putElementTrack(track);
            }
        },
        button: (event: string, key: string, element: Element) => {
            if (event === 'click') {
                const track = this.textElementEvent.newTrack(key);

                track.label = element.value;
                track.type = '点击';
                this.putElementTrack(track);
            }
        },
        checkbox: (event: string, key: string, element: Element) => {
            if (event === 'click') {
                const track = this.textElementEvent.newTrack(key);
                track.label = element.name;
                track.value = element.value;
                track.type = '选择';
                this.putElementTrack(track);
            }
        },
        file: (event: string, key: string, element: Element) => {
            if (event === 'change') {
                const track = this.textElementEvent.newTrack(key);

                track.label = element.name;
                let value = '';
                for (let i = 0; i < element.files.length; i++) {
                    if (i !== 0) {
                        value += ',';
                    }
                    value += element.files[i].name;
                }
                track.type = '选择';
                track.value = value;
                this.putElementTrack(track);
            }
        },
        image: (event: string, key: string, element: Element) => {
            if (event === 'click') {
                const track = this.textElementEvent.newTrack(key);
                track.label = element.name;
                track.value = element.name;
                track.type = '点击';
                this.putElementTrack(track);
            }
        },
        radio: (event: string, key: string, element: Element) => {
            if (event === 'click') {
                const track = this.textElementEvent.newTrack(key);
                track.label = element.name;
                track.value = element.value;
                track.type = '选择';
                this.putElementTrack(track);
            }
        },
        reset: (event: string, key: string, element: Element) => {
            if (event === 'click') {
                const track = this.textElementEvent.newTrack(key);
                track.label = element.value;
                track.type = '点击';
                this.putElementTrack(track);
            }
        },
        submit: (event: string, key: string, element: Element) => {
            if (event === 'click') {
                const track = this.textElementEvent.newTrack(key);
                track.label = element.value;
                track.value = element.value;
                track.type = '点击';
                this.putElementTrack(track);
            }
        },
        text: (event: string, key: string, element: Element) => {
            if (event === 'blur') {
                const track = this.tempTrack[key];
                if (!track) { return; }
                track.endTime = new Date().getTime();
                track.value = element.value;
                track.type = '录入';
                delete this.tempTrack[key];
                this.putElementTrack(track);
            }

            if (event === 'focus') {
                const track: Track = {
                    key,
                    label: element.placeholder,
                    type: element.nodeName,
                    startTime: new Date().getTime(),
                };

                this.tempTrack[key] = track;
            }

        },
        select: (event: string, key: string, element: Element) => {
            if (event === 'change') {
                const track = this.textElementEvent.newTrack(key);
                track.value = element.value;
                track.type = '选择';
                this.putElementTrack(track);
            }
        },
    };

    constructor(option: MMTextOption) {
        super(option);
        this.bizServiceUrl = option.collectorServer;
        if (option.busDespositNo) {
            this.depositNo = option.busDespositNo;
        }
        this.tempTrack = {};
        this.trackMap = {};
    }

    // 监听属性值变化
    public start(): void {
        const that = this;
        const events = ['focus', 'blur', 'click', 'change'];
        events.forEach(function (event) {
            document.addEventListener(event, function (o) {
                const element = o.target;
                const key = that.getNodeKey(element);
                that.elementHandle(event, element, key);
            }, true);
        });

        that.listener = setInterval(function () {
            that.textUpload();
        }, 3000);

        window.onbeforeunload = (e: any) => {
            that.textUpload();
        };
    }

    public stop(): void {
        clearInterval(this.listener);
    }

    private textUpload(): void {
        if (JSON.stringify(this.trackMap) === '{}') {
            return;
        }
        const depositNo=this.depositNo || requestUtil.getDepositNo()
        if (!depositNo){
            return;
        }
        //  保存文本信息记录
        const requestUrl = this.bizServiceUrl + '/deposite/textCollection';
        const requestMethod = 'POST';
        const listenerRequest = requestUtil.getRequest('TEXTCOLLECTION');
        listenerRequest.body = {
            depositNo: depositNo,
            content: JSON.stringify(this.trackMap),
            seqNo: requestUtil.getTextNo(),
        };
        requestUtil.ajax({
            url: requestUrl,
            type: requestMethod,
            data: listenerRequest,
            dataType: 'json',
            contentType: 'application/json',
            async: true,
            authorization: requestUtil.getAuth(),
            success: (data: ResponseInfo) => {
                this.trackMap = {};
            },
        });

    }

    private getNodeKey(element: any) {
        // 获取节点名称
        const nodeName = element.nodeName;
        const type = element.type;
        let key = element.getAttribute('snpsnt_key');
        if (key == null) {
            let elements: Array<Element & EventTarget> = [];
            key = new Date().getTime();
            if (nodeName === 'INPUT' && ['checkbox', 'radio'].indexOf(type) > -1) {
                elements = Array.prototype.slice.call(document.getElementsByName(element.getAttribute('name')));
            } else {
                elements.push(element);
            }
            elements.forEach(function (ele) {
                ele.setAttribute('snpsnt_key', key);
            });
        }
        return key;
    }

    /**
     * 不同组件的规则定义
     */
    private elementHandle(event: string, element: any, key: string) {
        // 获取节点名称
        const nodeName = element.nodeName;
        const type: string = element.type;
        // 如果是input或者是select则监控
        if (nodeName === 'INPUT') {
            if (typeof this.textElementEvent[type] === 'function') {
                this.textElementEvent[type](event, key, element);
            }
        } else if (nodeName === 'SELECT') {
            this.textElementEvent['select'](event, key, element);
        } else if (nodeName === 'BUTTON') {
            this.textElementEvent['button2'](event, key, element);
        }
    }

    private putElementTrack(track: Track) {
        const trackOne = { value: track.value, type: track.type, startTime: track.startTime, endTime: track.endTime };
        let elementTrack = this.trackMap[track.key];
        if (!elementTrack) {
            elementTrack = {};
            elementTrack.label = track.label;
            elementTrack.track = [];
            this.trackMap[track.key] = elementTrack;
        }
        elementTrack.track.push(trackOne);
    };
}
